{"content": "1|# watchdog.ps1 — monitors GoldEWS bot health, alerts Telegram and auto-restarts.
2|# Designed to run every 5 minutes via Windows Task Scheduler.
3|#
4|# Behavior:
5|#   1. GET http://localhost:8000/health -> ok?
6|#   2. If ok        -> record last_seen_ok = now, clear alerted flag, exit.
7|#   3. If not ok    -> read last_seen_ok from state file.
8|#                      If >10 min stale AND haven't alerted yet:
9|#                         * Telegram alert to WATCHDOG_ADMIN_CHAT_ID
10|#                         * Enable + Start GoldEWS scheduled task
11|#                         * Mark alerted=true (don't spam every 5 min)
12|#                      Else: just log and exit.
13|#   4. State persisted in C:\gold_ews\logs\watchdog_state.json.
14|
15|$ErrorActionPreference = "Continue"
16|$stateFile  = "C:\gold_ews\logs\watchdog_state.json"
17|$envFile    = "C:\gold_ews\.env"
18|$logFile    = "C:\gold_ews\logs\watchdog.log"
19|$now        = [DateTime]::UtcNow
20|$nowIso     = $now.ToString("o")
21|
22|function Log-Line {
23|    param([string]$msg)
24|    $line = "$($nowIso) | $msg"
25|    try { Add-Content -Path $logFile -Value $line -Encoding UTF8 } catch {}
26|}
27|
28|# ---- Load .env (process scope) ------------------------------------------
29|$envVars = @{}
30|if (Test-Path $envFile) {
31|    Get-Content $envFile | ForEach-Object {
32|        if ($_ -match "^([^=]+)=(.*)$") {
33|            $envVars[$matches[1].Trim()] = $matches[2].Trim()
34|        }
35|    }
36|}
37|
38|# ---- Probe /health ------------------------------------------------------
39|$healthy = $false
40|try {
41|    $r = Invoke-WebRequest -Uri "http://localhost:8000/health" -UseBasicParsing -TimeoutSec 5
42|    if ($r.StatusCode -eq 200 -and $r.Content -match '"status":"ok"') {
43|        $healthy = $true
44|    }
45|} catch { }
46|
47|# ---- Load prior state ---------------------------------------------------
48|$state = [ordered]@{ last_seen_ok = $null; alerted = $false }
49|if (Test-Path $stateFile) {
50|    try {
51|        $loaded = Get-Content $stateFile -Raw | ConvertFrom-Json
52|        if ($loaded.last_seen_ok) { $state.last_seen_ok = $loaded.last_seen_ok }
53|        if ($loaded.alerted -ne $null) { $state.alerted = [bool]$loaded.alerted }
54|    } catch {
55|        Log-Line "WARN: failed to parse state file: $($_.Exception.Message)"
56|    }
57|}
58|
59|# ---- Decide action ------------------------------------------------------
60|if ($healthy) {
61|    $state.last_seen_ok = $nowIso
62|    if ($state.alerted) {
63|        Log-Line "INFO: bot recovered, clearing alert flag"
64|        $state.alerted = $false
65|        # Optional: send recovery confirmation to admin
66|        $adminId = $envVars["WATCHDOG_ADMIN_CHAT_ID"]
67|        $token   = $envVars["TELEGRAM_BOT_TOKEN"]
68|        if ($adminId -and $token) {
69|            try {
70|                $body = @{ chat_id = $adminId; text = "GoldEWS bot recovered at $nowIso" } | ConvertTo-Json -Compress
71|                Invoke-RestMethod -Uri "https://api.telegram.org/bot$token/sendMessage" -Method POST -ContentType "application/json" -Body $body -TimeoutSec 10 | Out-Null
72|            } catch {
73|                Log-Line "WARN: recovery telegram failed: $($_.Exception.Message)"
74|            }
75|        }
76|    } else {
77|        Log-Line "OK: health 200"
78|    }
79|} else {
80|    # Bot is unhealthy
81|    if (-not $state.last_seen_ok) {
82|        # First run, no baseline — establish one
83|        $state.last_seen_ok = $nowIso
84|        Log-Line "INFO: first observation, bot unhealthy, recording baseline"
85|    } else {
86|        $lastSeen = [DateTime]::Parse($state.last_seen_ok).ToUniversalTime()
87|        $downMin  = [math]::Round(($now - $lastSeen).TotalMinutes, 1)
88|        Log-Line "WARN: bot unhealthy, down for $downMin min (last_ok=$($state.last_seen_ok))"
89|
90|        if ($downMin -ge 10 -and -not $state.alerted) {
91|            $adminId = $envVars["WATCHDOG_ADMIN_CHAT_ID"]
92|            $token   = $envVars["TELEGRAM_BOT_TOKEN"]
93|
94|            # Try to recover the task
95|            try {
96|                Enable-ScheduledTask -TaskName GoldEWS -ErrorAction SilentlyContinue | Out-Null
97|                Start-ScheduledTask -TaskName GoldEWS -ErrorAction SilentlyContinue
98|                Log-Line "INFO: re-enabled and started GoldEWS task"
99|            } catch {
100|                Log-Line "ERROR: task restart failed: $($_.Exception.Message)"
101|            }
102|
103|            # Telegram alert
104|            if ($adminId -and $token) {
105|                try {
106|                    $msg  = "GoldEWS bot DOWN for $downMin min. Tried Enable+Start of task. Check VPS."
107|                    $body = @{ chat_id = $adminId; text = $msg } | ConvertTo-Json -Compress
108|                    Invoke-RestMethod -Uri "https://api.telegram.org/bot$token/sendMessage" -Method POST -ContentType "application/json" -Body $body -TimeoutSec 10 | Out-Null
109|                    Log-Line "INFO: telegram alert sent to $adminId"
110|                    $state.alerted = $true
111|                } catch {
112|                    Log-Line "ERROR: telegram alert failed: $($_.Exception.Message)"
113|                }
114|            } else {
115|                Log-Line "WARN: no WATCHDOG_ADMIN_CHAT_ID or TELEGRAM_BOT_TOKEN in .env; alert skipped"
116|                $state.alerted = $true
117|            }
118|        }
119|    }
120|}
121|
122|# ---- Persist state ------------------------------------------------------
123|try {
124|    $state | ConvertTo-Json -Compress | Set-Content -Path $stateFile -Encoding ASCII
125|} catch {
126|    Log-Line "ERROR: failed to write state: $($_.Exception.Message)"
127|}
